	const paddingRight = Number.parseInt(computedStyle.paddingRight || "0", 10);
	const paddingBottom = Number.parseInt(computedStyle.paddingBottom || "0", 10);
	const borderLeftWidth = Number.parseInt(computedStyle.borderLeftWidth || "0", 10);
	const borderTopWidth = Number.parseInt(computedStyle.borderTopWidth || "0", 10);
	const borderRightWidth = Number.parseInt(computedStyle.borderRightWidth || "0", 10);
	const borderBottomWidth = Number.parseInt(computedStyle.borderBottomWidth || "0", 10);
